15	var newlineReplacer = strings.NewReplacer("\r", " ", "\n", " ")
16	
17	// frontmatterSmuggleRegex matches reserved frontmatter keys in a body line, including quoted keys
18	// and whitespace before the colon, which a plain prefix check would miss.
19	var frontmatterSmuggleRegex = regexp.MustCompile(`(?i)^\s*["']?(verified|governance|generated|type|status|code_refs|stale_after)["']?\s*:`)
20	
21	func titleCase(s string) string {
22		if s == "" {
23			return ""
24		}
25		r := []rune(s)
26		r[0] = unicode.ToUpper(r[0])
27		return string(r)
28	}
