325	// resolveInBundle joins relPath onto bundleDir and refuses any result that
326	// resolves outside the bundle directory or targets reserved root files.
327	func resolveInBundle(bundleDir, relPath string) (string, error) {
328		absBundle, err := filepath.Abs(bundleDir)
329		if err != nil {
330			return "", fmt.Errorf("failed to resolve bundle directory: %w", err)
331		}
332	
333		if IsAbsPath(relPath) {
334			return "", fmt.Errorf("concept path %q must be a relative path", relPath)
335		}
336	
337		// Normalize backslashes to forward slashes before calling filepath.Clean
338		// to prevent Windows-style backslash traversal vectors (e.g. "..\..\file") on POSIX OS.
339		normRel := strings.ReplaceAll(relPath, "\\", "/")
340		cleanRel := filepath.Clean(normRel)
341		full := filepath.Join(absBundle, cleanRel)
342		rel, err := filepath.Rel(absBundle, full)
343		if err != nil {
344			return "", fmt.Errorf("failed to resolve concept path %q: %w", relPath, err)
345		}
346		relSlash := strings.ReplaceAll(rel, "\\", "/")
347		if relSlash == ".." || strings.HasPrefix(relSlash, "../") {
348			return "", fmt.Errorf("path traversal denied: concept path %q escapes bundle directory", relPath)
349		}
350		// Check reserved filenames on relative path (index.md anywhere, root log.md, root AGENTS.md)
351		relBase := filepath.Base(cleanRel)
352		normRel = filepath.ToSlash(rel)
353		if rel == "." || cleanRel == "." ||
354			strings.EqualFold(relBase, "index") || strings.EqualFold(relBase, "index.md") ||
355			strings.EqualFold(normRel, "log.md") || strings.EqualFold(normRel, "AGENTS.md") {
356			return "", fmt.Errorf("cannot write concept to reserved bundle file %q", relPath)
357		}
358	
359		// Security: prevent symlink-based path traversal and arbitrary file overwrite
360		realTarget, err := ensureWithinRoot(bundleDir, full)
361		if err != nil {
362			return "", err
363		}
364	
365		// Check reserved filenames and file type on symlink-resolved target
366		targetBase := filepath.Base(realTarget)
367		realRoot, err := filepath.EvalSymlinks(bundleDir)
368		if err != nil {
369			realRoot, _ = filepath.Abs(bundleDir)
370		} else {
371			realRoot, _ = filepath.Abs(realRoot)
372		}
373		targetRel, _ := filepath.Rel(realRoot, realTarget)
374		targetRel = filepath.ToSlash(targetRel)
375	
376		if strings.EqualFold(targetBase, "index.md") || strings.EqualFold(targetRel, "log.md") || strings.EqualFold(targetRel, "AGENTS.md") {
377			return "", fmt.Errorf("cannot write concept to reserved bundle file %q", relPath)
378		}
379		if !strings.HasSuffix(strings.ToLower(realTarget), ".md") {
380			return "", fmt.Errorf("concept target %q must be a markdown (.md) file", relPath)
381		}
382	
383		return realTarget, nil
384	}
