447	// SaveOptions controls bookkeeping and authoring metadata when persisting a concept.
448	type SaveOptions struct {
449		IsNew     bool
450		AutoLog   bool
451		AutoIndex bool
452		Actor     string
453	}
454	
455	// SaveConcept writes a concept file to disk and optionally executes automatic bookkeeping.
456	// The entire mutation (concept file write + parent index update + log entry) executes
457	// inside a cross-process bundle write lock, and performs an optimistic concurrency check
458	// when persisting an existing concept loaded via LoadBundle.
459	func SaveConcept(bundleDir string, c *Concept, opts SaveOptions) error {
460		if c.ID == "" && c.Path != "" {
461			c.ID = strings.TrimSuffix(c.Path, ".md")
462		}
463		if err := ValidateConceptID(c.ID); err != nil {
464			return fmt.Errorf("invalid concept ID: %w", err)
465		}
466	
467		if _, err := resolveInBundle(bundleDir, c.Path); err != nil {
468			return err
469		}
470	
471		return WithBundleLock(bundleDir, func() error {
472			return saveConceptLocked(bundleDir, c, opts)
473		})
474	}
475	
476	func saveConceptLocked(bundleDir string, c *Concept, opts SaveOptions) error {
477		if c.ID == "" && c.Path != "" {
478			c.ID = strings.TrimSuffix(c.Path, ".md")
479		}
480		if err := ValidateConceptID(c.ID); err != nil {
481			return fmt.Errorf("invalid concept ID: %w", err)
482		}
483	
484		fullPath, err := resolveInBundle(bundleDir, c.Path)
485		if err != nil {
486			return err
487		}
488	
489		// Update generated timestamp & actor
490		actor := strings.TrimSpace(opts.Actor)
491		if actor == "" {
492			actor = "agent/okf-tool"
493		}
494		if err := ensureNoForgedHumanVerification(fullPath, c, actor, opts.IsNew); err != nil {
495			return err
496		}
497	
498		// Stage 2b: Optimistic Concurrency Check (CAS) when updating a concept loaded from disk
499		if !opts.IsNew && c.sourceHash != "" {
500			// #nosec G304 -- fullPath is validated and confined to bundleDir by resolveInBundle
501			if diskData, readErr := os.ReadFile(fullPath); readErr == nil {
502				if hashConceptContent(string(diskData)) != c.sourceHash {
503					return fmt.Errorf("%w: concept %q was modified on disk since it was loaded", ErrConcurrentModification, c.Path)
504				}
505			}
506		}
507	
508		c.Generated = &Generated{
509			By: actor,
510			At: time.Now().UTC().Format(time.RFC3339),
511		}
512	
513		if err := sanitizeConceptMetadata(c); err != nil {
514			return err
515		}
516	
517		c.Type = strings.TrimSpace(c.Type)
518		c.Title = strings.TrimSpace(c.Title)
519		if c.Description != "" {
520			c.Description = strings.TrimSpace(c.Description)
521		}
522	
523		if err := os.MkdirAll(filepath.Dir(fullPath), 0o755); err != nil {
524			return fmt.Errorf("failed to create directory: %w", err)
525		}
526	
527		raw := SerializeConcept(c)
528		if err := atomicWriteFile(fullPath, []byte(raw), 0o644); err != nil {
529			return fmt.Errorf("failed to write concept: %w", err)
530		}
531		c.RawContent = raw
532		if c.sourceHash != "" {
533			c.sourceHash = hashConceptContent(raw)
534		}
535	
536		// Automated Bookkeeping
537		if opts.AutoIndex {
538			if err := updateParentIndexLocked(bundleDir, c); err != nil {
539				return fmt.Errorf("failed to update parent index: %w", err)
540			}
541		}
542	
543		if opts.AutoLog {
544			entryType := "Update"
545			desc := fmt.Sprintf("Updated concept `%s`.", c.Path)
546			if opts.IsNew {
547				entryType = "Creation"
548				desc = fmt.Sprintf("Documented concept `%s` (%s).", c.Path, c.Title)
549			}
550			if err := appendLogEntryLocked(bundleDir, entryType, desc); err != nil {
551				return fmt.Errorf("failed to append log entry: %w", err)
552			}
553		}
554	
555		return nil
556	}
557	
558	// UpdateConcept loads the latest concept state from bundleDir, applies mutateFn,
559	// and saves the updated concept (including optional index and log bookkeeping)
560	// atomically inside a single cross-process bundle write lock.
561	func UpdateConcept(bundleDir, conceptID string, opts SaveOptions, mutateFn func(c *Concept) error) (*Concept, error) {
562		cleanID := strings.TrimSpace(strings.TrimSuffix(conceptID, ".md"))
563		if err := ValidateConceptID(cleanID); err != nil {
564			return nil, fmt.Errorf("invalid concept ID: %w", err)
565		}
566	
567		var result *Concept
568		err := WithBundleLock(bundleDir, func() error {
569			b, err := LoadBundle(bundleDir)
570			if err != nil {
571				return fmt.Errorf("failed to load bundle: %w", err)
572			}
573	
574			c, ok := b.Concepts[cleanID]
575			if !ok {
576				return fmt.Errorf("%w: '%s' in %s", ErrConceptNotFound, cleanID, bundleDir)
577			}
578	
579			updated := *c
580			if err := mutateFn(&updated); err != nil {
581				return err
582			}
583	
584			opts.IsNew = false
585			if err := saveConceptLocked(bundleDir, &updated, opts); err != nil {
586				return err
587			}
588			result = &updated
589			return nil
590		})
591		if err != nil {
592			return nil, err
593		}
594		return result, nil
595	}
596	
597	// RelateConcepts creates a relative markdown link between source and target concepts.
598	func RelateConcepts(bundleDir, sourceID, targetID, relationDesc, actor string) error {
599		relationDesc = strings.TrimSpace(newlineReplacer.Replace(relationDesc))
600	
601		sourceID = strings.TrimSpace(strings.TrimSuffix(sourceID, ".md"))
602		targetID = strings.TrimSpace(strings.TrimSuffix(targetID, ".md"))
603	
604		if err := ValidateConceptID(sourceID); err != nil {
605			return fmt.Errorf("invalid source concept ID: %w", err)
606		}
607		if err := ValidateConceptID(targetID); err != nil {
608			return fmt.Errorf("invalid target concept ID: %w", err)
609		}
610		if sourceID == targetID {
611			return fmt.Errorf("cannot relate concept to itself (%s)", sourceID)
612		}
613	
614		return WithBundleLock(bundleDir, func() error {
615			b, err := LoadBundle(bundleDir)
616			if err != nil {
617				return fmt.Errorf("failed to load bundle: %w", err)
618			}
619	
620			srcConcept, ok := b.Concepts[sourceID]
621			if !ok {
622				return fmt.Errorf("source concept '%s' not found", sourceID)
623			}
624	
625			tgtConcept, ok := b.Concepts[targetID]
626			if !ok {
627				return fmt.Errorf("target concept '%s' not found", targetID)
628			}
629	
630			// Compute relative path from source's directory to target
631			srcDir := filepath.Dir(srcConcept.Path)
632			relPath, err := filepath.Rel(srcDir, tgtConcept.Path)
633			if err != nil {
634				return fmt.Errorf("failed to compute relative path: %w", err)
635			}
636			relPath = filepath.ToSlash(relPath)
637	
638			linkText := tgtConcept.Title
639			if linkText == "" {
640				linkText = filepath.Base(targetID)
641			}
642	
643			relStatement := fmt.Sprintf("\n- Related to [%s](%s)", linkText, relPath)
644			if relationDesc != "" {
645				relStatement = fmt.Sprintf("\n- [%s](%s): %s", linkText, relPath, relationDesc)
646			}
647			if hasRelationship(srcConcept.Body, relPath, relationDesc) {
648				return nil
649			}
650	
651			srcConcept.Body = insertRelationship(srcConcept.Body, strings.TrimPrefix(relStatement, "\n"))
652	
653			if err := saveConceptLocked(bundleDir, srcConcept, SaveOptions{
654				IsNew:     false,
655				AutoLog:   false,
656				AutoIndex: false,
657				Actor:     actor,
658			}); err != nil {
659				return fmt.Errorf("failed to save related concept: %w", err)
660			}
661	
662			logDesc := fmt.Sprintf("Linked `%s` to `%s`.", srcConcept.Path, tgtConcept.Path)
663			if relationDesc != "" {
664				logDesc = fmt.Sprintf("Linked `%s` to `%s` (%s).", srcConcept.Path, tgtConcept.Path, relationDesc)
665			}
666			return appendLogEntryLocked(bundleDir, "Update", logDesc)
667		})
668	}
669	
670	func hasRelationship(body, relPath, relationDesc string) bool {
671		lines := strings.Split(body, "\n")
672		start, end, ok := relatedSectionBounds(lines)
673		if !ok {
674			return false
675		}
676		inFence := false
677		for _, line := range lines[start:end] {
678			trimmed := strings.TrimSpace(line)
679			if strings.HasPrefix(trimmed, "```") {
680				inFence = !inFence
681				continue
682			}
683			if inFence {
684				continue
685			}
686			clean := trimmed
687			if strings.HasPrefix(clean, "- ") || strings.HasPrefix(clean, "* ") {
688				clean = clean[2:]
689			}
690			if relationDesc == "" {
691				if (strings.HasPrefix(trimmed, "- Related to [") || strings.HasPrefix(trimmed, "* Related to [") || strings.HasPrefix(clean, "Related to [") || strings.HasPrefix(clean, "[")) && strings.Contains(clean, "]("+relPath+")") {
692					return true
693				}
694				continue
695			}
696			if (strings.HasPrefix(clean, "[") || strings.HasPrefix(trimmed, "- [") || strings.HasPrefix(trimmed, "* [")) && (strings.HasSuffix(trimmed, "]("+relPath+"): "+relationDesc) || strings.HasSuffix(clean, "]("+relPath+"): "+relationDesc)) {
697				return true
698			}
699		}
700		return false
701	}
702	
703	func insertRelationship(body, relLine string) string {
704		lines := strings.Split(strings.TrimRight(body, "\n"), "\n")
705		_, end, ok := relatedSectionBounds(lines)
706		if !ok {
707			return strings.TrimRight(body, "\n") + "\n\n# Related Concepts\n" + relLine + "\n"
708		}
709	
710		before := strings.TrimRight(strings.Join(lines[:end], "\n"), "\n")
711		after := strings.TrimLeft(strings.Join(lines[end:], "\n"), "\n")
712		if after == "" {
713			return before + "\n" + relLine + "\n"
714		}
715		return before + "\n" + relLine + "\n\n" + after + "\n"
716	}
717	
718	func parseHeading(line string) (int, string) {
719		trimmed := strings.TrimSpace(line)
720		if !strings.HasPrefix(trimmed, "#") {
721			return 0, ""
722		}
723		level := 0
724		for level < len(trimmed) && trimmed[level] == '#' {
725			level++
726		}
727		if level > 6 || level == len(trimmed) || trimmed[level] != ' ' {
728			return 0, ""
729		}
730		title := strings.TrimSpace(trimmed[level:])
731		return level, title
732	}
733	
734	func isRelatedHeading(title string) bool {
735		norm := strings.TrimSpace(strings.ToLower(title))
736		for len(norm) > 0 {
737			r := rune(norm[0])
738			if (r >= '0' && r <= '9') || r == '.' || r == '-' || r == ')' || r == ' ' || r == ':' {
739				norm = strings.TrimSpace(norm[1:])
740			} else {
741				break
742			}
743		}
744		return norm == "related concepts" || norm == "related" || strings.HasPrefix(norm, "related concepts")
745	}
746	
747	func relatedSectionBounds(lines []string) (int, int, bool) {
748		inFence := false
749		start := -1
750		startLevel := 0
751		for i, line := range lines {
752			trimmed := strings.TrimSpace(line)
753			if strings.HasPrefix(trimmed, "```") {
754				inFence = !inFence
755				continue
756			}
757			if inFence {
758				continue
759			}
760			if start == -1 {
761				if level, title := parseHeading(line); level > 0 && isRelatedHeading(title) {
762					start = i + 1
763					startLevel = level
764				}
765				continue
766			}
767			if level, _ := parseHeading(line); level > 0 && level <= startLevel {
768				return start, i, true
769			}
770		}
771		if start != -1 {
772			return start, len(lines), true
773		}
774		return 0, 0, false
775	}
