57	// RunMCPServer runs the Model Context Protocol stdio server for an OKF bundle.
58	func RunMCPServer(bundleDir string) error {
59		return RunMCPServerIO(bundleDir, os.Stdin, os.Stdout)
60	}
61	
62	const maxMCPLineLength = 4 * 1024 * 1024 // 4MB maximum JSON-RPC message size
63	
64	func readBoundedLine(r *bufio.Reader, maxLen int) ([]byte, bool, error) {
65		var line []byte
66		for {
67			chunk, isPrefix, err := r.ReadLine()
68			if err != nil {
69				if err == io.EOF && len(line) > 0 {
70					return line, false, nil
71				}
72				return nil, false, err
73			}
74			line = append(line, chunk...)
75			if len(line) > maxLen {
76				for isPrefix && err == nil {
77					_, isPrefix, err = r.ReadLine()
78				}
79				return nil, true, nil
80			}
81			if !isPrefix {
82				break
83			}
84		}
85		return line, false, nil
86	}
87	
88	// RunMCPServerIO runs the MCP server on the provided reader and writer.
89	func RunMCPServerIO(bundleDir string, in io.Reader, out io.Writer) error {
90		rootDir := os.Getenv("OKF_MCP_ROOT")
91		if rootDir == "" {
92			if bundleDir != "" && bundleDir != "." {
93				// The root is derived from the bundle's own path, so make that path
94				// absolute first: resolveBundleDir joins a relative bundle path to the
95				// root, and a relative "docs/knowledge" would otherwise be joined to
96				// its own parent and resolve to "docs/docs/knowledge".
97				if absBundle, err := filepath.Abs(bundleDir); err == nil {
98					bundleDir = absBundle
99				}
100				cleanBundle := filepath.Clean(bundleDir)
101				rootDir = filepath.Dir(cleanBundle)
102				if rootDir == "" {
103					rootDir = "."
104				}
105			} else {
106				rootDir = "."
107			}
108		}
109	
110		absRoot, err := filepath.Abs(rootDir)
111		if err == nil {
112			if evalRoot, err := filepath.EvalSymlinks(absRoot); err == nil {
113				absRoot = evalRoot
114			}
115			rootDir = absRoot
116		}
117	
118		s := &mcpServer{
119			bundleDir: bundleDir,
120			rootDir:   rootDir,
121			writer:    out,
122		}
123	
124		reader := bufio.NewReader(in)
125		for {
126			line, tooLarge, err := readBoundedLine(reader, maxMCPLineLength)
127			if err != nil {
128				if err == io.EOF {
129					return nil
130				}
131				return err
132			}
133			if tooLarge {
134				rawNull := json.RawMessage("null")
135				s.sendError(&rawNull, -32700, "Parse error: request exceeds 4MB maximum size")
136				continue
137			}
138	
139			trimmed := strings.TrimSpace(string(line))
140			if len(trimmed) == 0 {
141				continue
142			}
143	
144			var req jsonRPCRequest
145			if err := json.Unmarshal(line, &req); err != nil {
146				rawNull := json.RawMessage("null")
147				s.sendError(&rawNull, -32700, "Parse error")
148				continue
149			}
150	
151			s.handleRequest(req)
152		}
153	}
154	
155	func (s *mcpServer) sendResponse(id *json.RawMessage, result any) {
156		if id == nil || string(*id) == "null" {
157			// Per JSON-RPC 2.0 and MCP spec, never send a response to a notification
158			return
159		}
160		resp := jsonRPCResponse{
161			JSONRPC: "2.0",
162			ID:      id,
163			Result:  result,
164		}
165		data, _ := json.Marshal(resp)
166		s.mu.Lock()
167		defer s.mu.Unlock()
168		_, _ = s.writer.Write(append(data, '\n'))
169	}
170	
171	func (s *mcpServer) sendError(id *json.RawMessage, code int, message string) {
172		if (id == nil || string(*id) == "null") && code != -32700 {
173			// Per JSON-RPC 2.0 and MCP spec, never reply to a notification
174			return
175		}
176		resp := jsonRPCResponse{
177			JSONRPC: "2.0",
178			ID:      id,
179			Error: &rpcError{
180				Code:    code,
181				Message: message,
182			},
183		}
184		data, _ := json.Marshal(resp)
185		s.mu.Lock()
186		defer s.mu.Unlock()
187		_, _ = s.writer.Write(append(data, '\n'))
188	}
