11	// TestSaveConceptRejectsTraversal verifies that concept paths containing ".."
12	// segments or absolute paths are refused instead of writing outside the bundle directory.
13	func TestSaveConceptRejectsTraversal(t *testing.T) {
14		root := t.TempDir()
15		bundle := filepath.Join(root, "knowledge")
16		if err := InitBundle(bundle); err != nil {
17			t.Fatalf("InitBundle: %v", err)
18		}
19	
20		cases := []struct {
21			name string
22			path string
23		}{
24			{"direct parent escape", "../evil.md"},
25			{"nested escape", "a/b/../../../evil.md"},
26			{"escape via trailing dots", "project/../../evil.md"},
27			{"windows backslash traversal", "..\\evil.md"},
28			{"nested windows backslash escape", "a\\b\\..\\..\\..\\evil.md"},
29		}
30	
31		for _, tc := range cases {
32			t.Run(tc.name, func(t *testing.T) {
33				c := &Concept{
34					ID:    strings.TrimSuffix(tc.path, ".md"),
35					Path:  tc.path,
36					Type:  "Fact",
37					Title: "Evil",
38					Body:  "should never be written",
39				}
40				if err := SaveConcept(bundle, c, SaveOptions{IsNew: true, AutoLog: true, AutoIndex: true, Actor: "test"}); err == nil {
41					t.Fatalf("SaveConcept(%q): expected traversal error, got nil", tc.path)
42				}
43			})
44		}
45	
46		// Nothing may have been written next to the bundle directory.
47		entries, err := os.ReadDir(root)
48		if err != nil {
49			t.Fatalf("ReadDir: %v", err)
50		}
51		for _, e := range entries {
52			if e.Name() != "knowledge" {
53				t.Errorf("unexpected entry created outside bundle: %s", e.Name())
54			}
55		}
56	}
