204			if len(resultsAbs) != 2 || resultsAbs[0].ConceptID != "convention/style" || resultsAbs[1].ConceptID != "architecture/storage" {
205				t.Errorf("unexpected results for absolute path %s: %v", absPath, resultsAbs)
