210	func TestGovernanceAndCodeRefsValidation(t *testing.T) {
211		tempDir := t.TempDir()
212		bundleDir := filepath.Join(tempDir, "knowledge")
213		if err := os.MkdirAll(bundleDir, 0o755); err != nil {
214			t.Fatal(err)
215		}
216	
217		// Create valid source file
218		srcDir := filepath.Join(tempDir, "pkg", "auth")
219		if err := os.MkdirAll(srcDir, 0o755); err != nil {
220			t.Fatal(err)
221		}
222		if err := os.WriteFile(filepath.Join(srcDir, "auth.go"), []byte("package auth"), 0o644); err != nil {
223			t.Fatal(err)
224		}
225	
226		// Create a concept with invalid governance
227		b := &Bundle{
228			RootPath:    bundleDir,
229			DeclaredVer: "0.2",
230			Concepts: map[string]*Concept{
231				"architecture/bad-gov": {
232					Path:        "architecture/bad-gov.md",
233					Type:        "architecture",
234					Title:       "Bad Gov",
235					Description: "Has invalid governance field",
236					Governance:  "super-strict",
237				},
238				"architecture/stale-ref": {
239					Path:        "architecture/stale-ref.md",
240					Type:        "architecture",
241					Title:       "Stale Ref",
242					Description: "Points to non-existent code",
243					Governance:  "constraint",
244					CodeRefs:    []string{"pkg/auth/auth.go", "pkg/deleted/old.go"},
245				},
246				"architecture/traversal-ref": {
247					Path:        "architecture/traversal-ref.md",
248					Type:        "architecture",
249					Title:       "Traversal Ref",
250					Description: "Attempts path traversal",
251					Governance:  "constraint",
252					CodeRefs:    []string{"../../etc/passwd", "/etc/shadow"},
253				},
254			},
255			Indexes:      make(map[string]string),
256			Graph:        make(map[string][]string),
257			InboundGraph: make(map[string][]string),
258		}
259	
260		res := Validate(b, ValidateOptions{Strict: true, Drift: true})
261	
262		// Check that invalid governance produced a GateFinding
263		foundGovError := false
264		for _, f := range res.GateFindings {
265			if filepath.Base(f) != "" && (f == "architecture/bad-gov.md: governance 'super-strict' is not constraint|hold|context") {
266				foundGovError = true
267				break
268			}
269		}
270		if !foundGovError {
271			t.Errorf("expected gate finding for invalid governance, got: %v", res.GateFindings)
272		}
273	
274		// Check that path traversal in code_refs produced GateFindings
275		foundTraversalError := slices.Contains(res.GateFindings, "architecture/traversal-ref.md: code_refs '../../etc/passwd' contains forbidden '..' traversal")
276		foundAbsError := slices.Contains(res.GateFindings, "architecture/traversal-ref.md: code_refs '/etc/shadow' must be a relative path")
277		if !foundTraversalError || !foundAbsError {
278			t.Errorf("expected gate findings for traversal and absolute code_refs, got: %v", res.GateFindings)
279		}
280	
281		// Check that drift warning was produced for "pkg/deleted/old.go"
282		foundDriftWarning := slices.Contains(res.Warnings, "architecture/stale-ref.md: code_refs 'pkg/deleted/old.go' points to non-existent path")
283		if !foundDriftWarning {
284			t.Errorf("expected drift warning for missing code_ref, got: %v", res.Warnings)
285		}
286	}
